window.FILM_WORK_PROMPTS={"work_id":"src-a0002b5b2796776c","records":[{"work_id":"src-a0002b5b2796776c","frame_id":"FG-cfecd110c704e672","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment007.jpg","source_page":"https://film-grab.com/2020/07/15/the-adjustment-bureau/","scene":"仰视视角下的城市高楼群，深蓝色夜空布满云层，几栋黑色建筑剪影耸立，窗户透出零星暖黄灯光，画面中无可见人物。","analysis":"构图采用低角度仰拍，三栋主要建筑呈三角形分布，占据画面大部分空间。建筑主体为黑色剪影，与深蓝色天空形成强烈明暗对比。窗户灯光呈点状分布，暖黄色调在冷色背景中突出。云层纹理清晰，增加了天空的层次感。","prompt":"仰视视角城市夜景，三栋高层建筑剪影从下向上延伸，占据画面左右及中央位置。深蓝色夜空布满流动云层，建筑窗户透出稀疏暖黄色灯光，形成点状光斑。左侧建筑较宽，中央建筑呈梯形向上收窄，右侧建筑占据画面右边缘。建筑主体呈纯黑色，与冷色调天空形成高对比度。画面无可见人物，整体氛围静谧而压抑，低分辨率质感，城市峡谷般的空间感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:28-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment007.jpg","observed_dimensions":[500,268],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-f13a5bfb4230f1a7","origin":"visual"},{"work_id":"src-a0002b5b2796776c","frame_id":"FG-959edeb665f8ddc8","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment020.jpg","source_page":"https://film-grab.com/2020/07/15/the-adjustment-bureau/","scene":"昏暗的室内走廊，一名身穿深色衣物的人影站在走廊尽头的一扇门前。走廊两侧墙壁呈灰蓝色，右侧墙面挂有几幅画框，天花板嵌有筒灯，地面铺有地毯。","analysis":"构图采用单点透视，视线沿走廊向深处延伸。人物位于画面远端，全身轮廓可见，呈站立姿态，因距离较远显得较小。环境占据画面绝大部分，营造出封闭感。光线主要来自天花板上的嵌入式筒灯，发出冷白色光，照亮了部分天花板和地面，墙壁大部分处于阴影中，整体色调偏冷，明暗对比强烈。","prompt":"这是一张低分辨率的室内走廊画面，色调阴冷昏暗。画面采用纵深透视，一条狭长的走廊向远处延伸，两侧是灰蓝色的墙壁。右侧墙壁上挂着几幅深色边框的画作，左侧墙壁较为平整。天花板较低，嵌有几盏圆形的筒灯，发出冷白色的光，在地面和天花板上形成光斑。走廊尽头有一扇深色的门，门前站着一个身穿深色长衣的人影，全身轮廓可见，正面向门站立。地面铺着深色地毯，整体氛围压抑、静谧，光影层次分明，呈现出一种悬疑的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:35-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment020.jpg","observed_dimensions":[500,268],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-fd21bac8a86af9ec","origin":"visual"},{"work_id":"src-a0002b5b2796776c","frame_id":"FG-4c807b16e9d870f4","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment033.jpg","source_page":"https://film-grab.com/2020/07/15/the-adjustment-bureau/","scene":"两名身穿深色西装、头戴黑色礼帽的男子并排站立在街道上，右侧男子手持文件夹，背景为红砖建筑立面。","analysis":"画面截取人物腰部以上，两人占据前景主要位置，左侧人物身形略宽，右侧人物手持深色文件夹。背景为红砖墙面与排列整齐的窗户，建筑线条垂直。光线为自然日光，人物面部受光均匀，西装呈现深黑色块，与背景红砖的暖色调形成对比，整体色彩层次分明。","prompt":"低分辨率画面，两名男子并排站立于户外街道，均身着深色西装、白衬衫并系深色领带，头戴黑色礼帽。左侧男子面朝前方，右侧男子手持深色文件夹，神情略显惊讶。背景为多层红砖建筑，可见多扇矩形窗户及底层商铺门面。自然光照明，人物面部清晰，衣物呈现深色质感，背景建筑细节因分辨率较低而略显模糊，整体色调偏冷，红砖墙面提供暖色背景衬托。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:41-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment033.jpg","observed_dimensions":[500,268],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-1b865d744b57b34c","origin":"visual"},{"work_id":"src-a0002b5b2796776c","frame_id":"FG-26cf2e0793c6c0eb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment046.jpg","source_page":"https://film-grab.com/2020/07/15/the-adjustment-bureau/","scene":"一名身穿深色西装的短发男子侧身坐于黑暗车厢内，面朝右侧。背景透过车窗可见模糊的城市夜景，散布着粉色、白色和青色的散景光斑。","analysis":"画面采用低调照明，人物面部仅受微弱侧光勾勒，大部分身体隐没在阴影中。构图将人物置于画面中央偏左，右侧大面积留黑。背景光斑色彩丰富但虚化严重，与前景深沉的黑色形成强烈明暗对比，营造出静谧且压抑的视觉氛围。","prompt":"低分辨率电影静帧，画面主体为一名身穿深色西装、白色衬衫并系着深色领带的短发男子。他侧身坐于黑暗的车厢内，身体朝向右侧，面部轮廓在微弱光线下清晰可见，神情平静。背景是模糊的城市夜景，透过车窗可见散落的粉色、白色和青色光斑，呈现出明显的散景效果。整体色调极暗，大面积黑色阴影占据画面右侧及下方，仅保留人物面部和背景光点的高光，光影对比强烈，营造出一种沉静、神秘的夜间氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:46-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment046.jpg","observed_dimensions":[500,268],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-daf4e589551998f4","origin":"visual"},{"work_id":"src-a0002b5b2796776c","frame_id":"FG-999697059ec653e5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment059.jpg","source_page":"https://film-grab.com/2020/07/15/the-adjustment-bureau/","scene":"一男一女背对镜头站立，手牵手面向空旷的蓝色看台体育场，前景为绿色草坪与红褐色跑道。","analysis":"画面采用平视视角，人物位于前景下方，占据画面约三分之一高度，背景是巨大的多层看台，环境占比极大。人物仅可见上半身及大腿部分，左侧女性着黑色无袖裙，右侧男性着白衬衫戴深色帽。光线均匀柔和，色彩以看台的深蓝、草地的绿和跑道的红褐为主，明暗对比不强烈。","prompt":"低分辨率画面，一男一女背对镜头站立在体育场边缘，两人手牵手。左侧女性长发，身穿黑色无袖连衣裙；右侧男性戴深色圆顶帽，身穿白色短袖衬衫和深色裤子。两人面向前方广阔的绿色草坪，背景是巨大的多层深蓝色看台，看台呈弧形向上延伸，占据画面上半部分。前景脚下是红褐色跑道。整体光线均匀，色调偏冷，呈现出空旷、静谧的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:52-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/adjustment059.jpg","observed_dimensions":[500,268],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-71d384e887367ffb","origin":"visual"}]};